/// What turns one character into many sims. Top Gear, talent compare and Droptimizer ask the same question - a base character, a set of substitutions, a ranked answer - so they are one request shape with one planner behind it; mode says which of the three asked, and it is also the request's kind.
public struct BulkSpec: Codable, Sendable, Equatable {
    public let mode: String
    /// A drops request needs at least one and a talents request carries none; a gear request needs at least one candidate, talent loadout, set or consumable list between them.
    public let candidates: [Candidate]?
    /// A talents request needs at least one, and carries no candidates and no consumable lists: everything but the talents is locked.
    public let talents: [TalentLoadout]?
    /// Gear mode only; a set on any other mode is refused.
    public let sets: [GearSet]?
    /// Alternative consumable lists tried as candidates in gear mode: each inner list REPLACES character.consumes for that combination, so "flask or elixirs" is a dimension of the product rather than a thing the player has to run twice. An empty inner list is legal and means "no consumables". Gear mode only.
    public let consumables: [[String]]?
    /// Slots that are never substituted, whatever the candidate list says. It is the page's "keep what I have here".
    public let locked: [String]?
    /// How many stages the planner runs and how many iterations the last one gets. iterations must be that last stage's count: 3000 for fast and for normal, 10000 for high.
    public let precision: String
    /// The lane's combination cap, echoed into the request so a saved row says what bounded it. POST /v1/sims/run sets it itself - it is the server's to set, not a control the client holds - and refuses an expansion above it with cap_exceeded rather than silently trimming. A result saved through POST /v1/sims must carry the cap its own lane ran under.
    public let cap: Int?

    public init(
        mode: String,
        candidates: [Candidate]? = nil,
        talents: [TalentLoadout]? = nil,
        sets: [GearSet]? = nil,
        consumables: [[String]]? = nil,
        locked: [String]? = nil,
        precision: String,
        cap: Int? = nil
    ) {
        self.mode = mode
        self.candidates = candidates
        self.talents = talents
        self.sets = sets
        self.consumables = consumables
        self.locked = locked
        self.precision = precision
        self.cap = cap
    }
}

/// The calendar link (W3-C17). url is the link a calendar app subscribes to, shown once: it is non-null on the call that makes the link and on a reset, and null on every later read, because only the token's SHA-256 is stored. An app keeps the url it was shown in its secure store; with none, it offers Reset link to show a new one.
public struct CalendarFeed: Codable, Sendable, Equatable {
    /// https://api.foreversixty.gg/v1/calendar/{token}.ics; the token is 256 random bits, base64url (43 characters).
    public let url: String?
    /// When the live link was made.
    public let createdAt: Date

    public init(
        url: String? = nil,
        createdAt: Date
    ) {
        self.url = url
        self.createdAt = createdAt
    }
}

/// One item the planner may substitute in.
public struct Candidate: Codable, Sendable, Equatable {
    /// The planner slot, or "" for "wherever it fits", which is how a ring, a trinket or a one-hander is offered. A slot named in bulk.locked cannot also carry a candidate.
    public let slot: JSONValue?
    public let itemId: Int
    /// 0 inherits the equipped item's enchant for the slot it lands in, where that enchant fits; it does not mean "none".
    public let enchant: Int?
    public let suffix: Int?
    /// Where the candidate came from: equipped, bag, bank, search, "drop:<source id>" or "set:<name>". A prefixed origin must name something after the colon, and every candidate of a drops request must carry a "drop:" origin.
    public let origin: String
    /// The human name of the place the candidate came from - "Lucifron", "my AQ set". It travels into the result's substitution and into the row's headline, so nothing downstream has to join an origin id back to a name.
    public let sourceName: String?

    public init(
        slot: JSONValue? = nil,
        itemId: Int,
        enchant: Int? = nil,
        suffix: Int? = nil,
        origin: String,
        sourceName: String? = nil
    ) {
        self.slot = slot
        self.itemId = itemId
        self.enchant = enchant
        self.suffix = suffix
        self.origin = origin
        self.sourceName = sourceName
    }
}

