    public let gearSpec: String?
    public let gearSpecSource: String?
    public let supporter: Bool
    public let score: Int?
    public let tier: String?
    public let asOf: String?
    public let components: ScoreComponents?
    /// Each component's ceiling (gear 500, experience 700, parses 600, attendance 200, discipline 100): a bar is value over cap. Null with the score.
    public let componentCaps: ScoreComponentCaps?
    public let experience: ScoreExperience?

    public init(
        scoreHidden: Bool? = nil,
        character: CharacterProfileHeader,
        best: [CharacterFight] = [],
        history: [CharacterFight] = [],
        buildsSeen: [BuildSeen] = [],
        scoreHistory: [ScorePoint] = [],
        gear: [CharacterGearSlot] = [],
        gearGapTotal: Double? = nil,
        gearSpec: String? = nil,
        gearSpecSource: String? = nil,
        supporter: Bool,
        score: Int? = nil,
        tier: String? = nil,
        asOf: String? = nil,
        components: ScoreComponents? = nil,
        componentCaps: ScoreComponentCaps? = nil,
        experience: ScoreExperience? = nil
    ) {
        self.scoreHidden = scoreHidden
        self.character = character
        self.best = best
        self.history = history
        self.buildsSeen = buildsSeen
        self.scoreHistory = scoreHistory
        self.gear = gear
        self.gearGapTotal = gearGapTotal
        self.gearSpec = gearSpec
        self.gearSpecSource = gearSpecSource
        self.supporter = supporter
        self.score = score
        self.tier = tier
        self.asOf = asOf
        self.components = components
        self.componentCaps = componentCaps
        self.experience = experience
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        scoreHidden = try c.decodeIfPresent(Bool.self, forKey: .scoreHidden)
        character = try c.decode(CharacterProfileHeader.self, forKey: .character)
        best = try c.decodeIfPresent([CharacterFight].self, forKey: .best) ?? []
        history = try c.decodeIfPresent([CharacterFight].self, forKey: .history) ?? []
        buildsSeen = try c.decodeIfPresent([BuildSeen].self, forKey: .buildsSeen) ?? []
        scoreHistory = try c.decodeIfPresent([ScorePoint].self, forKey: .scoreHistory) ?? []
        gear = try c.decodeIfPresent([CharacterGearSlot].self, forKey: .gear) ?? []
        gearGapTotal = try c.decodeIfPresent(Double.self, forKey: .gearGapTotal)
        gearSpec = try c.decodeIfPresent(String.self, forKey: .gearSpec)
        gearSpecSource = try c.decodeIfPresent(String.self, forKey: .gearSpecSource)
        supporter = try c.decode(Bool.self, forKey: .supporter)
        score = try c.decodeIfPresent(Int.self, forKey: .score)
        tier = try c.decodeIfPresent(String.self, forKey: .tier)
        asOf = try c.decodeIfPresent(String.self, forKey: .asOf)
        components = try c.decodeIfPresent(ScoreComponents.self, forKey: .components)
        componentCaps = try c.decodeIfPresent(ScoreComponentCaps.self, forKey: .componentCaps)
        experience = try c.decodeIfPresent(ScoreExperience.self, forKey: .experience)
    }
}

