/// GET /v1/guilds/{id}/home. Verified members only.
public struct GuildHome: Codable, Sendable, Equatable {
    public let guild: GuildHomeGuild
    public let viewer: GuildHomeViewer
    public let claim: GuildClaimState
    public let summary: GuildSummary
    /// Omitted when it cannot be derived.
    public let standing: GuildStanding?
    /// The last 7 days.
    public let reports: [GuildReportRow]
    public let nextCursor: String?
    public let roster: [GuildRosterRow]
    /// [] for a non-officer.
    public let pending: [GuildRosterRow]
    public let members: [GuildMember]
    public let counts: GuildMemberCounts
    public let addonSnapshot: GuildAddonSnapshot?
    public let nextRaid: RaidLine?
    public let attendanceSource: String

    public init(
        guild: GuildHomeGuild,
        viewer: GuildHomeViewer,
        claim: GuildClaimState,
        summary: GuildSummary,
        standing: GuildStanding? = nil,
        reports: [GuildReportRow] = [],
        nextCursor: String? = nil,
        roster: [GuildRosterRow] = [],
        pending: [GuildRosterRow] = [],
        members: [GuildMember] = [],
        counts: GuildMemberCounts,
        addonSnapshot: GuildAddonSnapshot? = nil,
        nextRaid: RaidLine? = nil,
        attendanceSource: String
    ) {
        self.guild = guild
        self.viewer = viewer
        self.claim = claim
        self.summary = summary
        self.standing = standing
        self.reports = reports
        self.nextCursor = nextCursor
        self.roster = roster
        self.pending = pending
        self.members = members
        self.counts = counts
        self.addonSnapshot = addonSnapshot
        self.nextRaid = nextRaid
        self.attendanceSource = attendanceSource
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        guild = try c.decode(GuildHomeGuild.self, forKey: .guild)
        viewer = try c.decode(GuildHomeViewer.self, forKey: .viewer)
        claim = try c.decode(GuildClaimState.self, forKey: .claim)
        summary = try c.decode(GuildSummary.self, forKey: .summary)
        standing = try c.decodeIfPresent(GuildStanding.self, forKey: .standing)
        reports = try c.decodeIfPresent([GuildReportRow].self, forKey: .reports) ?? []
        nextCursor = try c.decodeIfPresent(String.self, forKey: .nextCursor)
        roster = try c.decodeIfPresent([GuildRosterRow].self, forKey: .roster) ?? []
        pending = try c.decodeIfPresent([GuildRosterRow].self, forKey: .pending) ?? []
        members = try c.decodeIfPresent([GuildMember].self, forKey: .members) ?? []
        counts = try c.decode(GuildMemberCounts.self, forKey: .counts)
        addonSnapshot = try c.decodeIfPresent(GuildAddonSnapshot.self, forKey: .addonSnapshot)
        nextRaid = try c.decodeIfPresent(RaidLine.self, forKey: .nextRaid)
        attendanceSource = try c.decode(String.self, forKey: .attendanceSource)
    }
}

