    public let characterKey: String?
    public let state: String
    /// leader, officer or member.
    public let rank: String
    public let className: String?
    public let level: Int?
    public let spec: String?
    public let seenAt: String?
    /// W3-C16: the spec catalogue's role for spec, else for the character's roster row; null when neither is known or consent withholds it. The apps' role chips read it, never a spec word.
    public let role: String?
    /// W3-C16: the full spec name, the catalogue's full_name ("Holy Priest", "Feral Druid (Bear)"); null with role.
    public let specName: String?
    /// W3-C16: the spec's talent-tab icon stem; null with role.
    public let specIcon: String?

    public init(
        name: String,
        characterKey: String? = nil,
        state: String,
        rank: String,
        className: String? = nil,
        level: Int? = nil,
        spec: String? = nil,
        seenAt: String? = nil,
        role: String? = nil,
        specName: String? = nil,
        specIcon: String? = nil
    ) {
        self.name = name
        self.characterKey = characterKey
        self.state = state
        self.rank = rank
        self.className = className
        self.level = level
        self.spec = spec
        self.seenAt = seenAt
        self.role = role
        self.specName = specName
        self.specIcon = specIcon
    }

    enum CodingKeys: String, CodingKey {
        case name
        case characterKey
        case state
        case rank
        case className = "class"
        case level
        case spec
        case seenAt
        case role
        case specName
        case specIcon
    }
}

