        error: String? = nil,
        aborted: Bool? = nil,
        combos: [Combo]? = nil,
        equipped: Estimate? = nil,
        stages: [Stage]? = nil,
        weights: [StatWeight]? = nil,
        sample: [SampleCast]? = nil,
        healing: HealingResult? = nil,
        tank: TankResult? = nil
    ) {
