        inCount: Int? = nil,
        late: Int? = nil,
        tanks: Int? = nil,
        healers: Int? = nil
    ) {
        self.raidId = raidId
        self.guildId = guildId
        self.guildName = guildName
        self.zone = zone
        self.zoneName = zoneName
        self.startsAt = startsAt
        self.inviteAt = inviteAt
        self.pullAt = pullAt
        self.endsAt = endsAt
        self.size = size
        self.signedUp = signedUp
        self.status = status
        self.my = my
        self.canSignUp = canSignUp
        self.zoneIcon = zoneIcon
        self.inCount = inCount
        self.late = late
        self.tanks = tanks
        self.healers = healers
    }

    enum CodingKeys: String, CodingKey {
        case raidId
        case guildId
        case guildName
        case zone
        case zoneName
        case startsAt
        case inviteAt
        case pullAt
        case endsAt
        case size
        case signedUp
        case status
        case my
        case canSignUp
        case zoneIcon
        case inCount = "in"
        case late
        case tanks
        case healers
    }
}

public struct WidgetUpgradePick: Codable, Sendable, Equatable {
    public let id: Int
    public let name: String
    public let quality: Int
    public let icon: String
    public let itemLevel: Int
    /// Where it comes from, Home's HomePick source_line. Always sent; optional for older snapshots.
    public let sourceLine: String?

    public init(
        id: Int,
        name: String,
        quality: Int,
        icon: String,
        itemLevel: Int,
        sourceLine: String? = nil
    ) {
        self.id = id
        self.name = name
        self.quality = quality
        self.icon = icon
        self.itemLevel = itemLevel
        self.sourceLine = sourceLine
    }
}

public struct WidgetUpgradeRow: Codable, Sendable, Equatable {
    public let slot: String
    public let slotLabel: String
    public let pick: WidgetUpgradePick
    /// null: `Gain not modelled yet`, drawn as `—`.
    public let gain: Double?

    public init(
        slot: String,
        slotLabel: String,
        pick: WidgetUpgradePick,
        gain: Double? = nil
    ) {
        self.slot = slot
        self.slotLabel = slotLabel
        self.pick = pick
        self.gain = gain
    }
}

/// The Home answer's first three rows in its order, with the whole list's count and total. Any state but ok has no rows and a sentence the widget shows as is.
public struct WidgetUpgrades: Codable, Sendable, Equatable {
    public let state: String
    public let sentence: String?
    public let count: Int
    public let totalGain: Double?
    public let unit: String
    public let rows: [WidgetUpgradeRow]

    public init(
        state: String,
        sentence: String? = nil,
        count: Int,
        totalGain: Double? = nil,
        unit: String,
        rows: [WidgetUpgradeRow] = []
    ) {
        self.state = state
        self.sentence = sentence
        self.count = count
        self.totalGain = totalGain
        self.unit = unit
        self.rows = rows
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        state = try c.decode(String.self, forKey: .state)
        sentence = try c.decodeIfPresent(String.self, forKey: .sentence)
        count = try c.decode(Int.self, forKey: .count)
        totalGain = try c.decodeIfPresent(Double.self, forKey: .totalGain)
        unit = try c.decode(String.self, forKey: .unit)
        rows = try c.decodeIfPresent([WidgetUpgradeRow].self, forKey: .rows) ?? []
    }
}

